import { RenderClient } from './RenderClient';
import { Carousel } from '@/types/index';
import fs from 'fs';
import path from 'path';

interface RenderPageProps {
  searchParams: Promise<{ slide?: string }>;
}

export default async function RenderPage({ searchParams }: RenderPageProps) {
  const params = await searchParams;
  const slideIndex = parseInt(params.slide || '0', 10);

  // Read carousel data from data/current-carousel.json
  const dataPath = path.join(process.cwd(), 'data', 'current-carousel.json');
  const carouselData = JSON.parse(fs.readFileSync(dataPath, 'utf-8')) as Carousel;

  return <RenderClient carousel={carouselData} slideIndex={slideIndex} />;
}